B.aRc=new A.a("\u0642\u0627\u0644\u062a \u0639\u0627\u0626\u0634\u0629: \u0641\u062c\u0647\u0632\u0646\u0627\u0647\u0645\u0627 \u0623\u062d\u062b \u0627\u0644\u062c\u0647\u0627\u0632\u060c \u0648\u0635\u0646\u0639\u0646\u0627 \u0644\u0647\u0645 \u0633\u0641\u0631\u0629 \u0641\u064a \u062c\u0631\u0627\u0628\u060c \u0641\u0642\u0637\u0645\u062a \u0623\u0633\u0645\u0627\u0621 \u0628\u0646\u062a \u0623\u0628\u064a \u0628\u0643\u0631 \u0642\u0637\u0639\u0629 \u0645\u0646 \u0646\u0637\u0627\u0642\u0647\u0627 \u0641\u0631\u0628\u0637\u062a \u0628\u0647 \u0639\u0644\u0649 \u0641\u0645 \u0627\u0644\u062c\u0631\u0627\u0628\u060c \u0641\u0628\u0630\u0644\u0643 \u0633\u0645\u064a\u062a \u0630\u0627\u062a \u0627\u0644\u0646\u0637\u0627\u0642\u064a\u0646\u060c \u062b\u0645 \u0644\u062d\u0642 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0648\u0623\u0628\u0648 \u0628\u0643\u0631 \u0628\u063a\u0627\u0631 \u0641\u064a \u062c\u0628\u0644 \u062b\u0648\u0631 \u0641\u0643\u0645\u0646\u0627 -\u0627\u0633\u062a\u062a\u0631\u0627 \u0641\u064a\u0647 \u062b\u0644\u0627\u062b \u0644\u064a\u0627\u0644\u064d- \u064a\u0628\u064a\u062a \u0639\u0646\u062f\u0647\u0645\u0627 \u0639\u0628\u062f \u0627\u0644\u0644\u0647 \u0628\u0646 \u0623\u0628\u064a \u0628\u0643\u0631 \u0648\u0647\u0648 \u063a\u0644\u0627\u0645 \u0634\u0627\u0628 \u062b\u0642\u0641 -\u0630\u0648 \u0641\u0637\u0646\u0629 \u0648\u0630\u0643\u0627\u0621- \u060c \u0644\u0642\u0646 -\u0639\u0646\u062f\u0647 \u062d\u064f\u0633\u0646 \u0627\u0644\u062a\u0644\u0642\u064a \u0644\u0645\u0627 \u064a\u0633\u0645\u0639\u0647- \u060c \u0641\u064a\u062f\u0644\u062c -\u0623\u062f\u0644\u062c \u0625\u0630\u0627 \u0633\u0627\u0631 \u0623\u0648\u0644 \u0627\u0644\u0644\u064a\u0644 \u0648\u0627\u062f\u0651\u0644\u062c \u0628\u0627\u0644\u062a\u0634\u062f\u064a\u062f \u0625\u0630\u0627 \u0633\u0627\u0631 \u0622\u062e\u0631\u0647- \u0645\u0646 \u0639\u0646\u062f\u0647\u0645\u0627 \u0628\u0633\u062d\u0631 -\u0642\u0628\u0644 \u0627\u0644\u0641\u062c\u0631- \u060c \u0641\u064a\u0635\u0628\u062d \u0645\u0639 \u0642\u0631\u064a\u0634 \u0628\u0645\u0643\u0629 \u0643\u0628\u0627\u0626\u062a\u060c \u0641\u0644\u0627 \u064a\u0633\u0645\u0639 \u0623\u0645\u0631\u0627 \u064a\u064e\u0643\u062a\u0627\u062f\u0627\u0646 -\u0623\u064a \u064a\u0637\u0644\u0628 \u0644\u0647\u0645\u0627 \u0641\u064a\u0647 \u0627\u0644\u0645\u0643\u0631\u0648\u0647 \u0648\u0647\u0648 \u0645\u0646 \u0627\u0644\u0643\u064a\u062f \u0628\u0647- \u0625\u0644\u0627 \u0648\u0639\u0627\u0647 \u062d\u062a\u0649 \u064a\u0623\u062a\u064a\u0647\u0645\u0627 \u0628\u062e\u0628\u0631 \u0630\u0644\u0643.",null)
B.aTR=new A.a("\u0648\u062d\u064a\u0646 \u064a\u062e\u062a\u0644\u0637 \u0627\u0644\u0638\u0644\u0627\u0645 \u064a\u0631\u0639\u0649 \u0639\u0644\u064a\u0647\u0645\u0627 \u0639\u0627\u0645\u0631 \u0628\u0646 \u0641\u0647\u064a\u0631\u0629 \u0645\u0648\u0644\u064a \u0623\u0628\u064a \u0628\u0643\u0631 \u0645\u0646\u062d\u0629 \u0645\u0646 \u063a\u0646\u0645 \u0641\u064a\u0631\u064a\u062d\u0647\u0627 \u0639\u0644\u064a\u0647\u0627 \u062d\u064a\u0646 \u062a\u0630\u0647\u0628 \u0633\u0627\u0639\u0629 \u0645\u0646 \u0627\u0644\u0639\u0634\u0627\u0621 \u0641\u064a\u0628\u062a\u0627\u0646 \u0641\u064a \u0631\u0650\u0633\u064e\u0644 \u0648\u0647\u0648 \u0644\u0628\u0646 \u0645\u0646\u062d\u062a\u0647\u0645\u0627 \u0648\u0631\u0636\u064a\u0641\u0647\u0645\u0627 -\u0623\u0649 \u0627\u0644\u0644\u0628\u0646 \u0627\u0644\u0645\u0631\u0636\u0648\u0641 \u0627\u0644\u0630\u064a \u0637\u0631\u062d \u0641\u064a\u0647 \u0627\u0644\u062d\u062c\u0627\u0631\u0629 \u0627\u0644\u0645\u062d\u0645\u0627\u0629 \u0644\u064a\u0630\u0647\u0628 \u0648\u064e\u062e\u064e\u0645\u064f\u0647 \u060c \u062d\u062a\u0649 \u064a\u0646\u0639\u0642 -\u0623\u064a \u0635\u0627\u062d \u0628\u0647\u0627 \u0648\u0632\u062c\u0631\u0647\u0627 \u0628\u0647\u0627 \u0639\u0627\u0645\u0631 \u0628\u0646 \u0641\u0647\u064a\u0631\u0629 \u0628\u063a\u0644\u0633 -\u0627\u0644\u063a\u0644\u0633 \u0623\u0649 \u0638\u0644\u0645\u0629 \u0622\u062e\u0631 \u0627\u0644\u0644\u064a\u0644 \u0625\u0630\u0627 \u0627\u062e\u062a\u0644\u0637\u062a \u0628\u0636\u0648\u0621 \u0627\u0644\u0635\u0628\u0627\u062d- \u064a\u0641\u0639\u0644 \u0630\u0644\u0643 \u0641\u064a \u0643\u0644 \u0644\u064a\u0644\u0629 \u0645\u0646 \u062a\u0644\u0643 \u0627\u0644\u0644\u064a\u0627\u0644\u064a \u0627\u0644\u062b\u0644\u0627\u062b.",null)
B.b2T=new A.a("\u0648\u0627\u0633\u062a\u0623\u062c\u0631 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0648\u0623\u0628\u0648 \u0628\u0643\u0631 \u0631\u062c\u0644\u0627 \u0645\u0646 \u0628\u0646\u064a \u0627\u0644\u062f\u064a\u0644 \u0648\u0647\u0648 \u0645\u0646 \u0628\u0646\u064a \u0639\u0628\u062f \u0628\u0646 \u0639\u062f\u064a \u0647\u0627\u062f\u064a\u0627 \u062e\u0631\u064a\u062a\u0627 \u0648\u0627\u0644\u062e\u0631\u064a\u062a \u0627\u0644\u0645\u0627\u0647\u0631 \u0628\u0627\u0644\u0647\u062f\u0627\u064a\u0629 \u0642\u062f \u063a\u0645\u0633 \u062d\u0644\u0641\u0627\u064b -\u0623\u064a \u0623\u062e\u0630 \u0628\u0646\u0635\u064a\u0628 \u0645\u0646 \u0639\u0642\u062f\u0647\u0645 \u0648\u062d\u0644\u0641\u0647\u0645 \u064a\u0623\u0645\u0646 \u0628\u0647\u0641\u064a \u0622\u0644 \u0627\u0644\u0639\u0627\u0635 \u0627\u0628\u0646 \u0648\u0627\u0626\u0644 \u0627\u0644\u0633\u0647\u0645\u064a\u060c \u0648\u0647\u0648 \u0639\u0644\u0649 \u062f\u064a\u0646 \u0643\u0641\u0627\u0631 \u0642\u0631\u064a\u0634\u060c \u0641\u0623\u0645\u0646\u0627\u0647 \u0641\u062f\u0641\u0639\u0627 \u0625\u0644\u064a\u0647 \u0631\u0627\u062d\u0644\u062a\u064a\u0647\u0645\u0627\u060c \u0648\u0648\u0627\u0639\u062f\u0627\u0647 \u063a\u0627\u0631 \u062b\u0648\u0631 \u0628\u0639\u062f \u062b\u0644\u0627\u062b \u0644\u064a\u0627\u0644 \u0628\u0631\u0627\u062d\u0644\u062a\u064a\u0647\u0645\u0627 \u0635\u0628\u062d \u062b\u0644\u0627\u062b\u060c \u0648\u0627\u0646\u0637\u0644\u0642 \u0645\u0639\u0647\u0645\u0627 \u0639\u0627\u0645\u0631 \u0628\u0647 \u0641\u0647\u064a\u0631\u0629\u060c \u0648\u0627\u0644\u062f\u0644\u064a\u0644 \u0641\u0623\u062e\u0630 \u0628\u0647\u0645 \u0637\u0631\u064a\u0642 \u0627\u0644\u0633\u0648\u0627\u062d\u0644.",null)
