B.ba2=new A.a("\u0648\u0636\u0639 \u0627\u0644\u0631\u0633\u0648\u0644 \ufdfa \u062e\u0637\u0629 \u0645\u062d\u0643\u0645\u0629 \u0644\u0645\u0648\u0627\u062c\u0647\u0629 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u0645\u0646 \u0642\u0631\u064a\u0634\u060c \u062d\u064a\u062b \u0627\u062e\u062a\u0627\u0631 \u0627\u0644\u0645\u0648\u0642\u0639 \u0627\u0644\u0645\u0646\u0627\u0633\u0628 \u0648\u0627\u0646\u062a\u062e\u0628 \u0645\u0646 \u064a\u0635\u0644\u062d \u0644\u0644\u0642\u062a\u0627\u0644 \u0648\u0631\u062f \u0645\u0646 \u0644\u0645 \u064a\u0643\u0646 \u0635\u0627\u0644\u062d\u0627\u064b \u0648\u0627\u062e\u062a\u0627\u0631 \u062e\u0645\u0633\u064a\u0646 \u0645\u0646\u0647\u0645 \u0644\u0644\u0631\u0645\u0627\u064a\u0629 \u0648\u0634\u062f\u062f \u0627\u0644\u0648\u0635\u064a\u0629 \u0639\u0644\u064a\u0647\u0645 \u0648\u0642\u0627\u0645 \u0628\u062a\u0642\u0633\u064a\u0645 \u0627\u0644\u062c\u064a\u0634 \u0627\u0644\u0649 \u062b\u0644\u0627\u062b \u0643\u062a\u0627\u0626\u0628 \u0648\u0623\u0639\u0637\u0649 \u0627\u0644\u0644\u0648\u0627\u0621 \u0644\u0623\u062d\u062f \u0623\u0641\u0631\u0627\u062f \u0627\u0644\u0643\u062a\u064a\u0628\u0629 \u0648\u0647\u0630\u0647 \u0627\u0644\u0643\u062a\u0627\u0626\u0628 \u0647\u064a:",null)
B.aOn=new A.a("\u0643\u062a\u064a\u0628\u0629 \u0627\u0644\u0645\u0647\u0627\u062c\u0631\u064a\u0646 \u0648\u0623\u0639\u0637\u0649 \u0648\u0644\u0648\u0627\u0621\u0647\u0627 \u0645\u0635\u0639\u0628 \u0628\u0646 \u0639\u0645\u064a\u0631 | \u0643\u062a\u064a\u0628\u0629 \u0627\u0644\u0623\u0648\u0633 \u0645\u0646 \u0627\u0644\u0623\u0646\u0635\u0627\u0631 \u0648\u0644\u0648\u0627\u0621\u0647\u0627 \u0623\u0633\u064a\u062f \u0628\u0646 \u062d\u0636\u064a\u0631 | \u0643\u062a\u064a\u0628\u0629 \u0627\u0644\u062e\u0632\u0631\u062c \u0645\u0646 \u0627\u0644\u0623\u0646\u0635\u0627\u0631 \u0648\u0644\u0648\u0627\u0621\u0647\u0627 \u0627\u0644\u062d\u0628\u0627\u0628 \u0628\u0646 \u0627\u0644\u0645\u0646\u0630\u0631.",null)
