B.aR8=new A.a("\u0646\u062c\u062f \u0641\u064a \u0628\u0639\u0636 \u0627\u0644\u0631\u0648\u0627\u064a\u0627\u062a: \u0623\u0646 \u0627\u0644\u0646\u0628\u064a \ufdfa \u062a\u0627\u0628\u0639 \u0623\u062e\u0628\u0627\u0631 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u0628\u0648\u0627\u0633\u0637\u0629 \u0628\u0639\u0636 \u0627\u062a\u0628\u0627\u0639\u0647\u060c \u062d\u062a\u0649 \u0628\u0639\u062f \u0631\u062c\u0648\u0639\u0647\u0645 \u0625\u0644\u0649 \u0645\u0643\u0629 \u0648\u0628\u0644\u063a\u0647 \u0645\u0642\u0627\u0644\u0629 \u0623\u0628\u064a \u0633\u0641\u064a\u0627\u0646 \u064a\u0644\u0648\u0645 \u0641\u064a\u0647\u0627 \u062c\u0646\u062f\u0647 \u0644\u0643\u0648\u0646\u0647\u0645 \u0644\u0645 \u064a\u0634\u0641\u0648\u0627 \u063a\u0644\u064a\u0644\u0647\u0645 \u0645\u0646 \u0645\u062d\u0645\u062f \u0648\u062c\u0646\u062f\u0647\u060c \u0641\u0639\u0646 \u0627\u0628\u0646 \u0639\u0628\u0627\u0633 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647\u0645\u0627 \u0642\u0627\u0644: \u0644\u0645\u0627 \u0627\u0646\u0635\u0631\u0641 \u0623\u0628\u0648 \u0633\u0641\u064a\u0627\u0646 \u0648\u0627\u0644\u0645\u0634\u0631\u0643\u0648\u0646 \u0645\u0646 \u0623\u062d\u062f \u0648\u0628\u0644\u063a\u0648\u0627 \u0627\u0644\u0631\u0651\u0648\u062d\u0627\u0621 - \u062a\u0628\u0639\u062f \u0639\u0646 \u0627\u0644\u0645\u062f\u064a\u0646\u0629 73 \u0643\u064a\u0644\u0648\u0645\u062a\u0631\u0627\u064b \u0641\u064a \u0637\u0631\u064a\u0642 \u0645\u0643\u0629 - \u0642\u0627\u0644 \u0623\u0628\u0648 \u0633\u0641\u064a\u0627\u0646: \u0644\u0627\u0645\u062d\u0645\u062f\u0627\u064b \u0642\u062a\u0644\u062a\u0645 \u0648\u0644\u0627 \u0627\u0644\u0643\u0648\u0627\u0639\u0628 \u0623\u0631\u062f\u0641\u062a\u0645 \u0634\u0631 \u0645\u0627\u0635\u0646\u0639\u062a\u0645\u060c \u0641\u0628\u0644\u063a \u0630\u0644\u0643 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u060c \u0648\u062a\u0641\u064a\u062f \u0647\u0630\u0647 \u0627\u0644\u0631\u0648\u0627\u064a\u0629 \u062e\u0628\u0631 \u0627\u0633\u062a\u0637\u0644\u0627\u0639 \u0627\u0644\u0631\u0633\u0648\u0644 \ufdfa \u0623\u0639\u062f\u0627\u0626\u0647 \u062d\u062a\u0649 \u0628\u0639\u062f \u0627\u0646\u062a\u0647\u0627\u0621 \u0627\u0644\u0645\u0639\u0631\u0643\u0629 \u0648\u0630\u0644\u0643 \u0644\u0643\u064a \u064a\u0637\u0645\u0626\u0646 \u0639\u0644\u0649 \u0639\u062f\u0645 \u0645\u0628\u0627\u063a\u062a\u062a\u0647\u0645 \u0644\u0647 \u0648\u0639\u0646\u062f\u0645\u0627 \u0633\u0645\u0639 \u0645\u0627\u0643\u0627\u0646\u062a \u062a\u0639\u0632\u0645 \u0639\u0644\u064a\u0647 \u0642\u0631\u064a\u0634 \u0645\u0646 \u0627\u0644\u0639\u0648\u062f\u0629 \u0625\u0644\u0649 \u0627\u0644\u0645\u062f\u064a\u0646\u0629 \u062e\u0631\u062c \u0628\u0645\u0646 \u062d\u0636\u0631\u0647 \u064a\u0648\u0645 \u0623\u062d\u062f \u0645\u0646 \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u062f\u0648\u0646 \u063a\u064a\u0631\u0647\u0645 \u0625\u0644\u0649 \u062d\u0645\u0631\u0627\u0621 \u0627\u0644\u0623\u0633\u062f.",null)
B.aHv=new A.a("\u0648\u0633\u0627\u0631 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0625\u0644\u0649 \u062d\u0645\u0631\u0627\u0621 \u0627\u0644\u0623\u0633\u062f \u0648\u0627\u0642\u062a\u0631\u0628 \u0628\u062c\u0646\u0648\u062f\u0647 \u0645\u0646 \u062c\u064a\u0634 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u0641\u0623\u0642\u0627\u0645 \u0641\u064a\u0647 \u062b\u0644\u0627\u062b\u0629 \u0623\u064a\u0627\u0645 \u064a\u062a\u062d\u062f\u0649 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u0641\u0644\u0645 \u064a\u062a\u0634\u062c\u0639\u0648\u0627 \u0639\u0644\u0649 \u0644\u0642\u0627\u0626\u0647 \u0648\u0646\u0632\u0627\u0644\u0647 \u0648\u0643\u0627\u0646 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0642\u062f \u0623\u0645\u0631 \u0628\u0625\u0634\u0639\u0627\u0644 \u0627\u0644\u0646\u064a\u0631\u0627\u0646 \u0641\u0643\u0627\u0646\u0648\u0627 \u064a\u0634\u0639\u0644\u0648\u0646 \u0641\u064a \u0648\u0642\u062a \u0648\u0627\u062d\u062f \u062e\u0645\u0633\u0645\u0627\u0626\u0629 \u0646\u0627\u0631.",null)
